$(".prop-item__top").click(function () {
    // if(window.innerWidth>576){
    //     return
    // }
    let parent = $(this).parents(".auto-info__row")
    let id = $(this).attr("data-id")
    $(parent).find(".auto-info__img").removeClass("_active")
    $(parent).find(`.auto-info__img[data-id="${id}"]`).addClass("_active")
    $(parent).find(".prop-item").removeClass("_open")
    $(parent).find(".prop-item__bottom").slideUp()
    $(this).parents(".prop-item").toggleClass("_open")
    $(this).siblings(".prop-item__bottom").slideToggle()
})

